<script lang="ts">
  import { generationProgress, generationSteps, type GenerationRun } from './generationProgress';
  export let run: GenerationRun | null = null;
  export let connectionLost = false;
  $: state = generationProgress(run);
</script>
<div class="generation-progress" aria-label="Meditation generation progress">
  <div class="progress-art" aria-hidden="true"><span class="page page-back"></span><span class="page page-front"><i></i><i></i><i></i></span><span class="small-sun"></span></div>
  <span class="eyebrow">{connectionLost ? 'Reconnecting' : state.halted ? 'Creation paused' : `Stage ${Math.min(state.index + 1,4)} of 4`}</span>
  <h2>{connectionLost ? 'Your practice may still be taking shape.' : state.halted ? 'Let’s pick this up gently.' : state.title}</h2>
  <p class="stage-description" role="status" aria-live="polite">{connectionLost ? 'The connection was lost. Reconnect to see the engine’s latest progress.' : state.detail}</p>
  <ol class="stage-rail">{#each generationSteps as step,index}<li class:done={index < state.index} class:current={index === state.index && !state.halted} aria-current={index === state.index ? 'step' : undefined}><span>{index < state.index ? '✓' : index + 1}</span><strong>{step}</strong><small>{index < state.index ? 'Complete' : index === state.index ? connectionLost ? 'Last update' : state.halted ? 'Paused' : 'In progress' : 'Up next'}</small></li>{/each}</ol>
  {#if state.stage === 'synthesizing' && state.segments}
    <div class="segment-progress"><label for="voice-progress">Narration passages <strong>{state.segments.completed} of {state.segments.total}</strong></label><progress id="voice-progress" value={state.segments.completed} max={state.segments.total}></progress></div>
  {:else if !connectionLost && !state.halted && state.index < 4}
    <div class="activity-track" aria-hidden="true"><span></span></div>
  {/if}
  <p class="progress-note">{state.stage === 'synthesizing' && state.segments ? 'Passage counts come from the local engine.' : 'This follows the engine’s stages. Timing depends on your device.'}</p>
</div>
